<script lang="ts">
import {onMount,onDestroy} from 'svelte';
import {api} from '../../lib/api';
import type {MemberBook} from '../../lib/member';
export let bookId:number;
let book:MemberBook|null=null;let error='';let stopped=false;
onMount(()=>{void load();});onDestroy(()=>{stopped=true;});
async function load(){error='';try{const value=await api<MemberBook>(`/api/member/books/${bookId}`);if(!stopped){book=value;document.title=`${value.title} · Home Library`;}}catch(e){if(!stopped)error=(e as Error).message;}}
</script>
<p><a href="/">← Back to the catalogue</a></p>
{#if error}<h1>Book unavailable</h1><p role="alert" class="library-error">{error}</p><button class="library-button secondary" onclick={load}>Try again</button>{:else if !book}<p role="status">Loading book…</p>{:else}
<article class="member-book"><div class="cover">{#if book.cover_url}<img src={book.cover_url} alt={`Cover of ${book.title}`}/>{:else}<div class="missing">{book.title}</div>{/if}</div><div><h1>{book.title}</h1>{#if book.subtitle}<p class="subtitle">{book.subtitle}</p>{/if}<p class="authors">{book.authors.join(', ')||'Author not recorded'}</p><p class="availability">{book.count===0?'No copies currently in the library':book.available===0?'All copies are currently on loan':`${book.available} of ${book.count} ${book.count===1?'copy':'copies'} available`}</p><dl>{#if book.publisher}<dt>Publisher</dt><dd>{book.publisher}</dd>{/if}{#if book.publication_date}<dt>Publication date</dt><dd>{book.publication_date}</dd>{/if}{#if book.first_published_year}<dt>First published</dt><dd>{book.first_published_year}</dd>{/if}{#if book.isbn}<dt>ISBN</dt><dd>{book.isbn}</dd>{/if}</dl>{#if book.description}<section><h2>About this book</h2><p class="description">{book.description}</p></section>{/if}{#if book.subjects?.length}<section><h2>Subjects</h2><ul class="subjects">{#each book.subjects as subject}<li>{subject}</li>{/each}</ul></section>{/if}<p class="library-help">Ask your librarian to borrow an available copy.</p></div></article>
{/if}
<style>.member-book{display:grid;grid-template-columns:minmax(160px,260px) minmax(0,1fr);gap:3rem;margin-block:2rem;max-width:68rem}.cover img{width:100%;height:auto;max-height:450px;object-fit:contain;object-position:top}.missing{min-height:300px;background:var(--app-soft);display:grid;place-items:center;padding:2rem;font-family:Georgia,serif;font-size:2rem}.member-book h1{font-family:Georgia,serif;font-size:clamp(2rem,5vw,3rem);line-height:1.15;overflow-wrap:anywhere}.subtitle{font-size:1.3rem;color:var(--app-muted);margin-block:.75rem}.authors{font-size:1.1rem}.availability{margin-block:1.5rem;color:var(--app-accent)}dl{display:grid;grid-template-columns:auto 1fr;gap:.6rem 1.25rem}dt{color:var(--app-muted)}dd{margin:0;overflow-wrap:anywhere}section{margin-block:2rem}h2{font-size:1.35rem;margin-bottom:1rem}.description{white-space:pre-wrap;line-height:1.7}.subjects{list-style:none;padding:0;display:flex;flex-wrap:wrap;gap:.5rem}.subjects li{padding:.4rem .7rem;background:var(--app-soft);border-radius:.3rem;font-size:.9rem}@media(max-width:600px){.member-book{grid-template-columns:1fr;gap:1.5rem}.cover{max-width:190px}}</style>
